content_template_css:
.ebook-product-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 1.25rem;
  align-items: start;
}

.ebook-product-card__cover {
  min-width: 0;
}

.ebook-product-card__cover img {
  display: block;
  width: min(100%, 360px);
  height: auto;
  margin-inline: auto;
}

.ebook-product-card__content {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 1rem;
}

.ebook-product-card__details {
  order: 1;
  display: grid;
  gap: 0;
  width: 100%;
  margin: 0;
  overflow: hidden;
  border: 1px solid currentColor;
  border-radius: 0.5rem;
}

.ebook-product-card__pr {
  order: 2;
  margin: 0;
  padding: 0.65rem 0.8rem;
  border: 1px solid currentColor;
  border-radius: 0.4rem;
  font-size: 14px;
  font-weight: 700;
  line-height: 1.5;
}

.ebook-product-card__stores {
  order: 3;
  display: grid;
  gap: 0.75rem;
}

.ebook-product-card__detail-row {
  display: grid;
  grid-template-columns: minmax(5.5rem, 32%) minmax(0, 1fr);
  margin: 0;
  border-bottom: 1px solid currentColor;
}

.ebook-product-card__detail-row:last-child {
  border-bottom: 0;
}

.ebook-product-card__detail-row dt,
.ebook-product-card__detail-row dd {
  min-width: 0;
  margin: 0;
  padding: 0.7rem 0.8rem;
  overflow-wrap: anywhere;
}

.ebook-product-card__detail-row dt {
  font-weight: 700;
}

@media (min-width: 768px) {
  .ebook-product-card {
    grid-template-columns: minmax(260px, 38%) minmax(0, 1fr);
    gap: 2rem;
  }

  .ebook-product-card__cover img {
    width: 100%;
    max-width: 360px;
  }

  .ebook-product-card__pr {
    order: 1;
  }

  .ebook-product-card__stores {
    order: 2;
  }

  .ebook-product-card__details {
    order: 3;
  }

  .ebook-product-card__detail-row {
    grid-template-columns: minmax(7rem, 28%) minmax(0, 1fr);
  }
}
